CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,public_id TEXT UNIQUE NOT NULL,product_id TEXT NOT NULL,product_version TEXT NOT NULL,amount INTEGER NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL,yookassa_payment_id TEXT UNIQUE,confirmation_url TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,paid_at INTEGER,canceled_at INTEGER,refunded_at INTEGER,token_key_version INTEGER,token_hash TEXT UNIQUE,last_error_code TEXT,last_error_message TEXT,receipt_status TEXT DEFAULT 'none');
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,session_hash TEXT UNIQUE NOT NULL,order_id TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,last_used_at INTEGER,revoked_at INTEGER);
CREATE TABLE IF NOT EXISTS payment_events(id TEXT PRIMARY KEY,payment_id TEXT,event_type TEXT,payload_hash TEXT,received_at INTEGER,processed_at INTEGER,processing_status TEXT,error_message TEXT,UNIQUE(payment_id,event_type,processing_status));
CREATE TABLE IF NOT EXISTS system_events(id TEXT PRIMARY KEY,severity TEXT,source TEXT,event_code TEXT,message TEXT,context TEXT,created_at INTEGER,resolved_at INTEGER);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status); CREATE INDEX IF NOT EXISTS idx_sessions_order ON sessions(order_id);
